16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$",
49	            message = "Phone number must be E.164: '+' followed by 8 to 15 digits")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "postcode")
56	    private String postcode;
57	
58	    @Column(name = "registration_date", columnDefinition = "DATE")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "customer_code")
62	    private String customerCode;
63	
64	    @Column(name = "household_id")
65	    private String householdId;
66	
67	    @Column(name = "namesake_count")
68	    private Integer namesakeCount;
69	
70	    @Column(name = "membership_number")
71	    private String membershipNumber;
72	
73	    @Transient
74	    private Boolean bulkSignupWarning;
75	
76	    @Transient
77	    private Integer householdMemberCount;
78	
79	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
80	    private Set<Pet> pets;
81	
82	    public String getAddress() {
83	        return this.address;
84	    }
85	
86	    public void setAddress(String address) {
87	        this.address = address;
88	    }
89	
90	    public String getCity() {
91	        return this.city;
92	    }
93	
94	    public void setCity(String city) {
95	        this.city = city;
96	    }
97	
98	    public String getTelephone() {
99	        return this.telephone;
100	    }
101	
102	    public void setTelephone(String telephone) {
103	        this.telephone = telephone;
104	    }
105	
106	    public String getEmail() {
107	        return this.email;
108	    }
109	
110	    public void setEmail(String email) {
111	        this.email = email;
112	    }
113	
114	    public String getPostcode() {
115	        return this.postcode;
116	    }
117	
118	    public void setPostcode(String postcode) {
119	        this.postcode = postcode;
120	    }
121	
122	    public LocalDate getRegistrationDate() {
123	        return this.registrationDate;
124	    }
125	
126	    public void setRegistrationDate(LocalDate registrationDate) {
127	        this.registrationDate = registrationDate;
128	    }
129	
130	    public String getCustomerCode() {
131	        return this.customerCode;
132	    }
133	
134	    public void setCustomerCode(String customerCode) {
135	        this.customerCode = customerCode;
136	    }
137	
138	    public String getHouseholdId() {
139	        return this.householdId;
140	    }
141	
142	    public void setHouseholdId(String householdId) {
143	        this.householdId = householdId;
144	    }
145	
146	    public Integer getNamesakeCount() {
147	        return this.namesakeCount;
148	    }
149	
150	    public void setNamesakeCount(Integer namesakeCount) {
151	        this.namesakeCount = namesakeCount;
152	    }
153	
154	    public String getMembershipNumber() {
155	        return this.membershipNumber;
156	    }
157	
158	    public void setMembershipNumber(String membershipNumber) {
159	        this.membershipNumber = membershipNumber;
160	    }
161	
162	    public Boolean getBulkSignupWarning() {
163	        return this.bulkSignupWarning;
164	    }
165	
166	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
167	        this.bulkSignupWarning = bulkSignupWarning;
168	    }
169	
170	    public Integer getHouseholdMemberCount() {
171	        return this.householdMemberCount;
172	    }
173	
174	    public void setHouseholdMemberCount(Integer householdMemberCount) {
175	        this.householdMemberCount = householdMemberCount;
176	    }
177	
178	    protected Set<Pet> getPetsInternal() {
179	        if (this.pets == null) {
180	            this.pets = new HashSet<>();
181	        }
182	        return this.pets;
183	    }
184	
185	    protected void setPetsInternal(Set<Pet> pets) {
186	        this.pets = pets;
187	    }
188	
189	    public List<Pet> getPets() {
190	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
191	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
192	        return Collections.unmodifiableList(sortedPets);
193	    }
194	
195	    public void setPets(List<Pet> pets) {
196	        this.pets = new HashSet<>(pets);
197	    }
198	
199	    public void addPet(Pet pet) {
200	        getPetsInternal().add(pet);
201	        pet.setOwner(this);
202	    }
203	
204	    /**
205	     * Return the Pet with the given name, or null if none found for this Owner.
206	     *
207	     * @param name to test
208	     * @return true if pet name is already in use
209	     */
210	    public Pet getPet(String name) {
211	        return getPet(name, false);
212	    }
213	
214	    /**
215	     * Return the Pet with the given name, or null if none found for this Owner.
216	     *
217	     * @param name to test
218	     * @return true if pet name is already in use
219	     */
220	    public Pet getPet(String name, boolean ignoreNew) {
221	        name = name.toLowerCase();
222	        for (Pet pet : getPetsInternal()) {
223	            if (!ignoreNew || !pet.isNew()) {
224	                String compName = pet.getName();
225	                compName = compName.toLowerCase();
226	                if (compName.equals(name)) {
227	                    return pet;
228	                }
229	            }
230	        }
231	        return null;
232	    }
233	
234	    public Pet getPet(Integer petId) {
235	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
236	    }
237	
238	    @Override
239	    public String toString() {
240	        return new ToStringCreator(this)
241	
242	            .append("id", this.getId())
243	            .append("new", this.isNew())
244	            .append("lastName", this.getLastName())
245	            .append("firstName", this.getFirstName())
246	            .append("address", this.address)
247	            .append("city", this.city)
248	            .append("telephone", this.telephone)
249	            .toString();
250	    }
251	}
