14	public class RespondWithOwnerCreated {
15	
16	    private static final Logger auditLogger = LoggerFactory.getLogger("AUDIT");
17	
18	    public void service(@Val Owner owner, OwnerMapper ownerMapper,
19	            ObjectResponse<ResponseEntity<OwnerDto>> response) {
20	        OwnerDto dto = ownerMapper.toOwnerDto(owner);
21	        auditLogger.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={}",
22	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), dto.getMembershipLevel());
23	        response.send(ResponseEntity.created(URI.create("/api/owners/" + owner.getId())).body(dto));
24	    }
25	}
