1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;
8	
9	/**
10	 * The registrationDate is optional. When absent the owner defaults to the server date in
11	 * {@link BuildOwner}. When supplied it must not be later than the server's current date; a future
12	 * date throws {@link FutureRegistrationDateException} for a 400. Runs before {@link BuildOwner} so
13	 * the business-day roll never masks a future date.
14	 */
15	public class ValidateRegistrationDate {
16	
17	    public void service(@Val OwnerFieldsDto request) throws FutureRegistrationDateException {
18	        LocalDate registrationDate = request.getRegistrationDate();
19	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
20	            throw new FutureRegistrationDateException(registrationDate);
21	        }
22	    }
23	}
