1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	            expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
25	    @Mapping(target = "membershipLevel",
26	            expression = "java(Math.min(3, 1 + ((owner.getEmail() != null && !owner.getEmail().isBlank()) ? 1 : 0) + ((owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) ? 1 : 0)))")
27	    @Mapping(target = "locality",
28	            expression = "java(org.springframework.samples.petclinic.rest.function.common.Localities.region(owner.getPostcode(), owner.getCity()))")
29	    @Mapping(target = "contactPreference",
30	            expression = "java((owner.getEmail() != null && !owner.getEmail().isBlank()) ? org.springframework.samples.petclinic.rest.dto.OwnerDto.ContactPreferenceEnum.EMAIL : org.springframework.samples.petclinic.rest.dto.OwnerDto.ContactPreferenceEnum.PHONE)")
31	    @Mapping(target = "identityKey",
32	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentityKey.of(owner))")
33	    @Mapping(target = "checkDigit",
34	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.CustomerCodeCheckDigit.of(owner.getCustomerCode()))")
35	    OwnerDto toOwnerDto(Owner owner);
36	
37	    Owner toOwner(OwnerDto ownerDto);
38	
39	    @Mapping(target = "id", ignore = true)
40	    @Mapping(target = "pets", ignore = true)
41	    Owner toOwner(OwnerFieldsDto ownerDto);
42	
43	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
44	
45	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
46	
47	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
48	        OwnerPageDto ownerPageDto = new OwnerPageDto();
49	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
50	        ownerPageDto.setPage(ownerPage.getNumber());
51	        ownerPageDto.setSize(ownerPage.getSize());
52	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
53	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
54	        return ownerPageDto;
55	    }
56	}
