4	import org.junit.jupiter.api.Test;
5	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
6	import tools.jackson.databind.node.ObjectNode;
7	
8	/** telephone-unique: duplicate detection is now the single identityKey
9	 * (telephone|email|householdId). Two owners with the same identity collide with 409. */
10	@Tag("cp03")
11	class Cp03Tests extends AcceptanceBase {
12	
13		@Test
14		void coreIdentityCollisionRejected() throws Exception {
15			ObjectNode a = ownerNode();
16			createOwnerOk(a);
17			// A pure full duplicate: identical in every identity-bearing field, so it must collide (409)
18			// under every later version of the key. Do NOT tweak b (e.g. sharesHousehold), which would
19			// de-sync the householdId and let the keys differ before makes householdId computed.
20			createOwner(a.deepCopy()).andExpect(status().isConflict());
21		}
22	}
