	@Test
	void coreDerivesAgeBand() throws Exception {
		ObjectNode o = ownerNode();
		o.put("birthDate", "1990-01-01");
		int id = createOwnerOk(o);
		getOwner(id).andExpect(jsonPath("$.ageBand").value("ADULT"));
	}

	/** Under 18 relative to the (weekday) registrationDate -> MINOR. */
	@Test
	void underEighteenIsMinor() throws Exception {
		ObjectNode o = ownerNode();
		o.put("registrationDate", "2020-06-15"); // Monday
		o.put("birthDate", "2010-06-15"); // age 10
		int id = createOwnerOk(o);
		getOwner(id).andExpect(jsonPath("$.ageBand").value("MINOR"));
	}

	/** Exactly 18 on the registrationDate -> ADULT (lower bound inclusive). */
	@Test
	void exactlyEighteenIsAdult() throws Exception {
		ObjectNode o = ownerNode();
		o.put("registrationDate", "2020-06-15");
		o.put("birthDate", "2002-06-15"); // turns 18 on the registration date
		int id = createOwnerOk(o);
		getOwner(id).andExpect(jsonPath("$.ageBand").value("ADULT"));
	}

	/** One day short of 18 -> still MINOR. */
	@Test
	void oneDayShortOfEighteenIsMinor() throws Exception {
		ObjectNode o = ownerNode();
		o.put("registrationDate", "2020-06-15");
		o.put("birthDate", "2002-06-16"); // 17 years, 364 days
		int id = createOwnerOk(o);
		getOwner(id).andExpect(jsonPath("$.ageBand").value("MINOR"));
	}

	/** Exactly 65 on the registrationDate -> SENIOR (lower bound inclusive). */
	@Test
	void exactlySixtyFiveIsSenior() throws Exception {
		ObjectNode o = ownerNode();
		o.put("registrationDate", "2020-06-15");
		o.put("birthDate", "1955-06-15"); // turns 65 on the registration date
		int id = createOwnerOk(o);
		getOwner(id).andExpect(jsonPath("$.ageBand").value("SENIOR"));
	}

	/** 64 -> still ADULT (upper bound of the adult band). */
	@Test
	void sixtyFourIsAdult() throws Exception {
		ObjectNode o = ownerNode();
		o.put("registrationDate", "2020-06-15");
		o.put("birthDate", "1955-06-16"); // 64 years, 364 days
		int id = createOwnerOk(o);
		getOwner(id).andExpect(jsonPath("$.ageBand").value("ADULT"));
	}

	/** No birthDate supplied -> ageBand omitted from the response. */
	@Test
	void absentBirthDateHasNoAgeBand() throws Exception {
		int id = createOwnerOk(ownerNode());
		getOwner(id).andExpect(jsonPath("$.ageBand").doesNotExist());
	}
}

